const clientesEntrada = $("Webhook").all();
const investimentosEntrada = $("Normalizando csv").all();

// 1. Procura clientes em qualquer nível do JSON
const clientesEncontrados = [];

function extrairClientes(dado) {
  if (Array.isArray(dado)) {
    for (const elemento of dado) {
      extrairClientes(elemento);
    }
    return;
  }

  if (!dado || typeof dado !== "object") return;

  if (
    dado.nome !== undefined &&
    dado.email !== undefined &&
    dado.saldo !== undefined &&
    dado.perfil !== undefined
  ) {
    clientesEncontrados.push(dado);
    return;
  }

  for (const valor of Object.values(dado)) {
    if (valor && typeof valor === "object") {
      extrairClientes(valor);
    }
  }
}

for (const item of clientesEntrada) {
  extrairClientes(item.json);
}

// 2. Remove clientes duplicados pelo e-mail
const clientes = [
  ...new Map(
    clientesEncontrados.map(cliente => [
      cliente.email,
      cliente
    ])
  ).values()
];

// 3. Extrai os investimentos normalizados
const investimentos = [];

function extrairInvestimentos(dado) {
  if (Array.isArray(dado)) {
    for (const elemento of dado) {
      extrairInvestimentos(elemento);
    }
    return;
  }

  if (!dado || typeof dado !== "object") return;

  if (
    dado.produto !== undefined &&
    dado.perfil !== undefined &&
    dado.minimo !== undefined
  ) {
    investimentos.push({
      perfil: dado.perfil,
      produto: dado.produto,
      minimo: Number(dado.minimo),
      rentabilidade: dado.rentabilidade
    });
    return;
  }

  for (const valor of Object.values(dado)) {
    if (valor && typeof valor === "object") {
      extrairInvestimentos(valor);
    }
  }
}

for (const item of investimentosEntrada) {
  extrairInvestimentos(item.json);
}

// 4. Valida as entradas
if (clientes.length === 0) {
  throw new Error(
    "Nenhum cliente encontrado. Confira a estrutura de saída do Webhook."
  );
}

if (investimentos.length === 0) {
  throw new Error(
    "Nenhum investimento encontrado. Confira a saída do nó Normalizando csv."
  );
}

// 5. Gera as possibilidades de cada cliente
return clientes.map(cliente => {
  const saldoTexto = String(cliente.saldo ?? "")
    .replace(/R\$/gi, "")
    .replace(/\s/g, "")
    .trim();

  const saldo = Number(
    saldoTexto.includes(",")
      ? saldoTexto.replace(/\./g, "").replace(",", ".")
      : saldoTexto
  );

  if (!Number.isFinite(saldo)) {
    throw new Error(
      `Saldo inválido para ${cliente.email}: ${cliente.saldo}`
    );
  }

  const compativeis = investimentos.filter(inv =>
    inv.perfil === cliente.perfil &&
    Number.isFinite(inv.minimo) &&
    inv.minimo <= saldo
  );

  const mensagens = compativeis.map(inv => ({
    produto: inv.produto,
    minimo: inv.minimo,
    rentabilidade: inv.rentabilidade,
    mensagem: `Olá ${cliente.nome}! Verificamos o seu perfil e, baseado no seu saldo de ${cliente.saldo}, o melhor investimento é o ${inv.produto}, com investimento mínimo de ${inv.minimo} e com rentabilidade de ${inv.rentabilidade}.`
  }));

  const mensagemEscolhida = mensagens.length > 0
    ? mensagens.reduce((maior, atual) =>
        atual.minimo > maior.minimo ? atual : maior
      )
    : null;

  return {
    json: {
      possibilidades: {
        nome: cliente.nome,
        email: cliente.email,
        saldo: cliente.saldo,
        perfil: cliente.perfil,
        mensagens,
        mensagemEscolhida
      }
    }
  };
});

const resposta = $input.first().json;
const texto = resposta.data ?? resposta.body;

if (typeof texto !== "string") {
  throw new Error("A resposta do CSV não é um texto.");
}

const linhas = texto
  .replace(/^\uFEFF/, "")
  .trim()
  .split(/\r?\n/);

if (linhas.length < 2) {
  throw new Error("O CSV não contém registros.");
}

// Detecta o separador do cabeçalho
const separador = linhas[0].includes(";") ? ";" : ",";

// Normaliza os nomes das colunas
const cabecalhos = linhas[0]
  .split(separador)
  .map(campo =>
    campo.trim()
      .replace(/^["']|["']$/g, "")
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
  );

const investimentos = linhas.slice(1)
  .filter(linha => linha.trim() !== "")
  .map((linha, indice) => {
    const valores = linha.split(separador)
      .map(valor =>
        valor.trim().replace(/^["']|["']$/g, "")
      );

    const registro = Object.fromEntries(
      cabecalhos.map((campo, i) => [
        campo,
        valores[i] ?? ""
      ])
    );

    // Aceita cabeçalhos alternativos
    const perfil = registro.perfil;
    const produto = registro.produto;
    const minimo = registro.minimo;
    const rentabilidade = registro.rentabilidade;

    if (
      perfil === undefined ||
      produto === undefined ||
      minimo === undefined ||
      rentabilidade === undefined
    ) {
      throw new Error(
        `Verifique os cabeçalhos do CSV na linha ${indice + 2}.`
      );
    }

    return {
      perfil,
      produto,
      minimo: minimo === "" ? "" : Number(minimo),
      rentabilidade: String(rentabilidade)
    };
  });

return [
  {
    json: {
      investimentos
    }
  }
];
